-- ⚠️ FIXTURE DE TESTE — NÃO EXECUTAR NO SUPABASE DE PRODUÇÃO.
-- Recria, num Postgres descartável, o mínimo que as migrações do PMOC esperam
-- encontrar: os papéis anon/authenticated e as tabelas de produção como stub
-- (equipamentos com os 171 registros reais de predio/local/area).
-- Serve para validar as migrações antes de rodá-las de verdade.
-- Uso: ver a seção "Validação local das migrações" do TESTES.md.

create role anon;
create role authenticated;

create table equipamentos (
  id integer primary key, area text, predio text, local text, tipo text
);

create table maq_ativos (id serial primary key, codigo text, nome text, local text);
create table transp_ativos (id serial primary key, codigo text, nome text, local text);
